integer hasl(5), hash(5), lo(5), hi(5), fbin(5), nmbin(5), pord(5), m(5)
double precision v(5)

# priority order: FMAX(3), VDD(2), RDS(1), ILEAK(4), VTH(5)
pord(1) = 3
pord(2) = 2
pord(3) = 1
pord(4) = 4
pord(5) = 5

# low / high limits in units of 0.001
hasl(1) = 1
hasl(2) = 1
hasl(3) = 1
hasl(4) = 1
hasl(5) = 1
hash(1) = 0
hash(2) = 1
hash(3) = 1
hash(4) = 1
hash(5) = 0
lo(1) = 144783
lo(2) = 44244
lo(3) = 211279
lo(4) = 312485
lo(5) = 368162
hi(1) = 0
hi(2) = 57356
hi(3) = 266253
hi(4) = 527767
hi(5) = 0

# fail bins; nmbin = 0 means skip when not measured
fbin(1) = 27
fbin(2) = 21
fbin(3) = 32
fbin(4) = 24
fbin(5) = 15
nmbin(1) = 34
nmbin(2) = 34
nmbin(3) = 0
nmbin(4) = 34
nmbin(5) = 34

read(5,*) n
for (i = 1; i <= n; i = i + 1) {
  read(5,*) x, y, (v(k), k = 1, 5)
  for (k = 1; k <= 5; k = k + 1) m(k) = nint(v(k) * 1000d0)

  bin = 0
  for (j = 1; j <= 5; j = j + 1) {
    if (bin == 0) {
      c = pord(j)
      if (v(c) == -9999d0) {
        if (nmbin(c) != 0) bin = nmbin(c)
      } else {
        if ((hasl(c) == 1) & (m(c) < lo(c))) bin = fbin(c)
        if ((hash(c) == 1) & (m(c) > hi(c))) bin = fbin(c)
      }
    }
  }

  if (bin == 0) {
    marg = 0
    for (k = 1; k <= 5; k = k + 1) {
      if (v(k) != -9999d0) {
        if (hasl(k) == 1) {
          d = abs(m(k) - lo(k))
          if (10 * d <= abs(lo(k))) marg = 1
        }
        if (hash(k) == 1) {
          d = abs(m(k) - hi(k))
          if (10 * d <= abs(hi(k))) marg = 1
        }
      }
    }
    if (marg == 1) {
      bin = 10
    } else {
      bin = 1
    }
  }

  write(6,10) x, y, bin
}
