hasl(2) = 1; lo(2) = 44.244d0; hash(2) = 1; hi(2) = 57.356d0; fb(2) = 21; nmb(2) = 34
hasl(3) = 1; lo(3) = 211.279d0; hash(3) = 1; hi(3) = 266.253d0; fb(3) = 32; nmb(3) = 0
hasl(4) = 1; lo(4) = 312.485d0; hash(4) = 1; hi(4) = 527.767d0; fb(4) = 24; nmb(4) = 34
hasl(5) = 1; lo(5) = 368.162d0; hash(5) = 0; hi(5) = 0d0; fb(5) = 15; nmb(5) = 34

