          dx = abs(v(c) - lo(c))
          if (10d0 * dx <= abs(lo(c))) marg = 1
        }
        if (hash(c) == 1) {
          dx = abs(v(c) - hi(c))
          if (10d0 * dx <= abs(hi(c))) marg = 1
        }
      }
