integer n, i, x, y, bin, done, marg
double precision f, g, il

read(5,*) n
do i = 1, n {
  read(5,*) x, y, f, g, il
  bin = 0
  done = 0

  # priority 1: GAIN (col 2)
  if (g == -9999d0) {
    bin = 2
    done = 1
  } else if (g > 520.473d0) {
    bin = 39
    done = 1
  }

  # priority 2: ILEAK (col 3)
  if (done == 0) {
    if (il == -9999d0) {
      bin = 2
      done = 1
    } else if (il < 305.719d0 | il > 366.081d0) {
      bin = 6
      done = 1
    }
  }

  # priority 3: FMAX (col 1)
  if (done == 0) {
    if (f == -9999d0) {
      bin = 2
      done = 1
    } else if (f > 590.038d0) {
      bin = 32
      done = 1
    }
  }

  # no test failed: marginal check (within 5% of a limit, or equal)
  if (done == 0) {
    marg = 0
    if (abs(g - 520.473d0) <= 0.05d0 * 520.473d0) marg = 1
    if (abs(il - 305.719d0) <= 0.05d0 * 305.719d0) marg = 1
    if (abs(il - 366.081d0) <= 0.05d0 * 366.081d0) marg = 1
    if (abs(f - 590.038d0) <= 0.05d0 * 590.038d0) marg = 1
    if (marg == 1) bin = 18
    else bin = 1
  }

  write(6,*) x, y, bin
}
end

