  # priority 1: TEMP (column 3), skip if not measured
  if (t != -9999d0) {
    if (t < 363.74d0) { bin = 11; done = 1 }
  }
  # priority 2: VDD (column 2), bin 7 if not measured
  if (done == 0) {
    if (vdd == -9999d0) {
      bin = 7; done = 1
    } else if (vdd < 76.692d0 | vdd > 96.708d0) {
      bin = 32; done = 1
    }
  }
  # priority 3: ILEAK (column 1), skip if not measured
  if (done == 0) {
    if (a != -9999d0) {
      if (a < 358.076d0) { bin = 27; done = 1 }
    }
  }
  write(6,*) x, y, bin
}
end

