integer n, i, k, c, bin, done, ix, iy
integer ord(4), nmb(4), fb(4)
double precision v(4), lo(4), hi(4), tol

# priority order: GAIN(3), RDS(2), TEMP(1), ILEAK(4)
ord(1) = 3
ord(2) = 2
ord(3) = 1
ord(4) = 4

# not-measured bin per column (0 = skip)
nmb(1) = 12
nmb(2) = 0
nmb(3) = 0
nmb(4) = 12

# fail bin per column
fb(1) = 3
fb(2) = 31
fb(3) = 17
fb(4) = 5

# limits ("-" high limit = 1d30, effectively none)
lo(1) = 241.542d0
hi(1) = 302.676d0
lo(2) = 83.229d0
hi(2) = 99.671d0
lo(3) = 283.243d0
hi(3) = 334.557d0
lo(4) = 79.118d0
hi(4) = 1d30

read(5,*) n
do i = 1, n {
  read(5,*) ix, iy, v(1), v(2), v(3), v(4)
  bin = 0
  done = 0
  for (k = 1; k <= 4; k = k + 1) {
    if (done == 0) {
      c = ord(k)
      if (abs(v(c) + 9999d0) < 0.5d0) {
        if (nmb(c) != 0) {
          bin = nmb(c)
          done = 1
        }
      } else if (v(c) < lo(c) | v(c) > hi(c)) {
        bin = fb(c)
        done = 1
      }
    }
  }
  if (done == 0) {
    bin = 1
    for (c = 1; c <= 4; c = c + 1) {
      if (abs(v(c) + 9999d0) >= 0.5d0) {
        tol = 0.1d0 * abs(lo(c))
        if (abs(v(c) - lo(c)) <= tol) bin = 9
        tol = 0.1d0 * abs(hi(c))
        if (abs(v(c) - hi(c)) <= tol) bin = 9
      }
    }
  }
  write(6,*) ix, iy, bin
}
end

