integer n, i, x, y, b, gv, rv, marg
double precision g, r
read(5,*) n
do i = 1, n {
  read(5,*) x, y, g, r
  gv = 0
  rv = 0
  if (g != -9999d0) gv = nint(g * 1000d0)
  if (r != -9999d0) rv = nint(r * 1000d0)
  b = 0
  # priority 1: RDS (limits 168.985 .. 245.607 in thousandths)
  if (r != -9999d0) {
    if (rv < 168985 | rv > 245607) {
      b = 4
    }
  }
  # priority 2: GAIN (limits 141.092 .. 178.908 in thousandths)
  if (b == 0) {
    if (g == -9999d0) {
      b = 2
    } else if (gv < 141092 | gv > 178908) {
      b = 18
    }
  }
  # no test failed: check marginality (|v - L| <= |L|/10, exact integer test)
  if (b == 0) {
    marg = 0
    if (g != -9999d0) {
      if (10 * abs(gv - 141092) <= 141092 | 10 * abs(gv - 178908) <= 178908) {
        marg = 1
      }
    }
    if (r != -9999d0) {
      if (10 * abs(rv - 168985) <= 168985 | 10 * abs(rv - 245607) <= 245607) {
        marg = 1
      }
    }
    if (marg == 1) {
      b = 11
    } else {
      b = 1
    }
  }
  write(6,*) x, y, b
}
end

integer n, i, x, y, bin, marg
double precision f, v, t, d

read(5,*) n
for (i = 1; i <= n; i = i + 1) {
  read(5,*) x, y, f, v, t, d
  bin = 0
  marg = 0

  # priority 1: VTH (not measured -> bin 5)
  if (v == -9999d0) {
    bin = 5
  } else if (v < 224.154d0 | v > 341.646d0) {
    bin = 36
  }

  # priority 2: FMAX (high limit only)
  if (bin == 0) {
    if (f != -9999d0) {
      if (f > 224.619d0) bin = 6
    }
  }

  # priority 3: TEMP
  if (bin == 0) {
    if (t != -9999d0) {
      if (t < 186.357d0 | t > 210.843d0) bin = 8
    }
  }

  # priority 4: VDD
  if (bin == 0) {
    if (d != -9999d0) {
      if (d < 58.608d0 | d > 86.592d0) bin = 25
    }
  }

  # no fail: check marginality (within 2% of own limits), else bin 1
  if (bin == 0) {
    if (f != -9999d0) {
      if (abs(f - 224.619d0) <= 0.02d0 * abs(224.619d0)) marg = 1
    }
    if (v != -9999d0) {
      if (abs(v - 224.154d0) <= 0.02d0 * abs(224.154d0)) marg = 1
      if (abs(v - 341.646d0) <= 0.02d0 * abs(341.646d0)) marg = 1
    }
    if (t != -9999d0) {
      if (abs(t - 186.357d0) <= 0.02d0 * abs(186.357d0)) marg = 1
      if (abs(t - 210.843d0) <= 0.02d0 * abs(210.843d0)) marg = 1
    }
    if (d != -9999d0) {
      if (abs(d - 58.608d0) <= 0.02d0 * abs(58.608d0)) marg = 1
      if (abs(d - 86.592d0) <= 0.02d0 * abs(86.592d0)) marg = 1
    }
    if (marg == 1) {
      bin = 34
    } else {
      bin = 1
    }
  }

  write(6,*) x, y, bin
}
end
